/** old picture frame -> new video frame (inverse of WARP, monotone binary search) */
export const toNew = (fo: number): number => { const n = WARP.length - 1; if (fo <= WARP[0]) return 0; if (fo >= WARP[n]) return n; let lo = 0, hi = n; while (hi - lo > 1) { const m = (lo + hi) >> 1; if (WARP[m] <= fo) lo = m; else hi = m; } return lo + (fo - WARP[lo]) / Math.max(1e-6, WARP[hi] - WARP[lo]); };
